// The delegated-routing store the API resolves against. Same URL the API uses
// (DELEGATED_ROUTING_URL); defaults to the local mock on :3001.
const ROUTING_URL = process.env.DELEGATED_ROUTING_URL ?? 'http://localhost:3001';

/**
 * Deterministically seed the network (delegated-routing) record for a name by
 * reading the signed record the API already persisted and PUTting it straight
 * into the routing store. The API's own publish to routing is fire-and-forget
 * and gets rate-limited/dropped under the full suite's load in CI, which would
 * otherwise leave the network record absent and make the seqFloor network-serve
 * case (Test 15) non-deterministic. This mirrors the suite's existing practice
 * of seeding preconditions directly (psql) rather than racing async side effects.
 */
async function seedNetworkRecord(ipnsName: string): Promise<void> {
  const hex = psqlQueryOne(
    `SELECT encode(signed_record, 'hex') FROM ipns_records WHERE ipns_name = '${ipnsName}'`
  );
  if (!hex) throw new Error(`no signed_record in DB for ${ipnsName} to seed routing`);
  const res = await fetch(`${ROUTING_URL}/routing/v1/ipns/${ipnsName}`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/vnd.ipfs.ipns-record' },
    body: new Uint8Array(Buffer.from(hex, 'hex')),
  });
  if (!res.ok) throw new Error(`routing seed PUT failed for ${ipnsName}: ${res.status}`);
}

/** Upload a small unique blob to IPFS and return its CID. */

