export const meta = {
  name: 'cr-584-fixes',
  description: 'Apply in-scope CodeRabbit fixes for PR #584 (one agent per disjoint file)',
  phases: [{ title: 'Fix', detail: 'one agent per file/finding' }],
}

const FIX_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {
    files: { type: 'array', items: { type: 'string' } },
    status: { type: 'string', enum: ['applied', 'skipped', 'partial'] },
    summary: { type: 'string' },
    changeDetails: { type: 'string' },
  },
  required: ['files', 'status', 'summary'],
}

const COMMON = `
Repo root: /Users/myankelev/Code/random/cipher-box (CipherBox monorepo).
Rules:
- Read the target file(s) first; verify the finding against the CURRENT code. If it is already fixed or the suggestion is stale/wrong, set status "skipped" with the reason in summary.
- Apply a MINIMAL, correct fix scoped ONLY to the assigned file(s). Match the surrounding code style and comment density. Use TypeScript string-literal unions, never enums.
- Do NOT run jest or any test suite. Do NOT run "pnpm api:generate". Do NOT git add/commit. Do NOT touch any other file.
- Return the structured result (files changed, status, a one-line summary, and a short changeDetails with the key lines).
`

const tasks = [
  {
    label: 'ipns.controller-openapi',
    prompt: `${COMMON}
File: apps/api/src/ipns/ipns.controller.ts

Two OpenAPI documentation findings:

(1) The tombstone endpoint (POST /ipns/tombstone, the handler that calls ipnsService.tombstoneRecord()) is missing a 404 response. tombstoneRecord() throws NotFoundException for a missing or unowned name. Add an @ApiResponse({ status: 404, ... }) decorator to that handler alongside its existing 200/400/401 responses, with a description like "IPNS name not found or not owned by the caller".

(2) The batch publish endpoint (the handler that calls ipnsService.publishBatch()) can now propagate a 410 Gone (error: IPNS_TOMBSTONED) when any record in the batch targets a tombstoned name. Add an @ApiResponse({ status: 410, ... }) decorator to that batch handler, describing the tombstoned-name case, consistent with how the single-publish endpoint documents 410.

Read the controller, find both handlers, and add the decorators matching the existing @ApiResponse style in this file. Do not regenerate the client.`,
  },
  {
    label: 'shares.controller-normalize',
    prompt: `${COMMON}
File: apps/api/src/shares/shares.controller.ts

Finding: in createShare, the response echoes dto.recipientPublicKey directly. The request validator accepts both bare "04..." and "0x04..." forms, but the response DTO documents the "0x04..." form, so the response shape becomes input-dependent. Normalize it: when building the CreateShareResponseDto, set recipientPublicKey to dto.recipientPublicKey.startsWith('0x') ? dto.recipientPublicKey : \`0x\${dto.recipientPublicKey}\`. Keep everything else unchanged.`,
  },
  {
    label: 'shares.service-23505',
    prompt: `${COMMON}
File: apps/api/src/shares/shares.service.ts (around the createShare save/catch, ~line 74-80)

Finding: the duplicate-detection in the catch uses a brittle err.message?.includes('duplicate key'). Replace it with a reliable Postgres unique-violation check on the error code 23505 (check (err as { code?: string; driverError?: { code?: string } }).code === '23505' || ...driverError?.code === '23505'). Keep the existing ConflictException('Share already exists for this item and recipient') mapping and re-throw/propagate all other errors unchanged. Match how other services in apps/api detect 23505 if there is an existing pattern (grep for "23505").`,
  },
  {
    label: 'share-invites.controller-query',
    prompt: `${COMMON}
Files: apps/api/src/shares/share-invites.controller.ts and (new) a query DTO file under apps/api/src/shares/dto/.

Finding: the listInvites handler (GET, ~line 91-95) trusts a rootIpnsName query param documented only via @ApiQuery({ required: true }); an omitted or malformed value still reaches shareInviteService.getInvitesForItem. Add runtime validation:
- First Read apps/api/src/shares/dto/create-invite.dto.ts and copy the EXACT validation decorators used on its rootIpnsName property (e.g. @IsString() + the canonical IPNS-name @Matches(...) regex).
- Create a small query DTO (e.g. GetInvitesForItemQueryDto) in apps/api/src/shares/dto/ with a rootIpnsName field carrying those same decorators.
- Change the controller handler to accept @Query() query: GetInvitesForItemQueryDto (relying on the global ValidationPipe) and pass query.rootIpnsName to the service. Preserve the @ApiQuery doc and the existing auth/user flow.
Do not regenerate the client.`,
  },
  {
    label: 'invite+share-dto-bound-generation',
    prompt: `${COMMON}
Files: apps/api/src/shares/dto/create-invite.dto.ts and apps/api/src/shares/dto/create-share.dto.ts

Finding: rootGeneration is validated only with @IsNumberString(), so an arbitrarily long numeric string can pass validation and then fail when persisted to the bigint "root_generation"/generation column. Bound it to the signed 64-bit bigint range at the DTO layer in BOTH files, consistently.
Preferred approach: keep @IsOptional()/@IsNumberString() and add a @Matches(...) (or a small custom validator) that rejects values outside 0 .. 9223372036854775807. A robust regex that caps the magnitude at the bigint max is acceptable, OR a @Validate custom constraint that does BigInt(value) <= 9223372036854775807n && BigInt(value) >= 0n. Pick whichever fits the existing validation style in these DTOs; apply the SAME bound to both create-invite.dto.ts and create-share.dto.ts (mirror them). Add a clear validation message.`,
  },
  {
    label: 'vault.service-affected',
    prompt: `${COMMON}
File: apps/api/src/vault/vault.service.ts (the catch block handling Postgres 23505 during root IPNS init, ~line 101-107)

Finding: when a 23505 unique-violation on ipns_name is caught, the code calls this.ipnsRecordRepository.update({ userId, ipnsName: dto.rootIpnsName }, { isRoot: true }) but never checks how many rows were affected. Because ipns_name is globally unique (not per-user), the conflicting row may belong to ANOTHER user, so the update affects 0 rows and initialization silently succeeds WITHOUT a root IpnsRecord. Capture the update result and, if (updateResult.affected ?? 0) === 0, throw a ConflictException (message like 'Root IPNS name is already associated with another record'). Ensure ConflictException is imported from @nestjs/common (add to the import if missing). Keep the non-23505 branch unchanged.`,
  },
  {
    label: 'migration-idempotent',
    prompt: `${COMMON}
File: apps/api/src/migrations/1750000000000-ApiSchemaCutover.ts (the ipns_records CREATE TABLE + CREATE INDEX pair, ~line 147-170)

Finding: per the project's migration protocol, every CREATE must be idempotent. The ipns_records create step is the only create not guarded. Change "CREATE TABLE \\"ipns_records\\" (" to "CREATE TABLE IF NOT EXISTS \\"ipns_records\\" (" and change the immediately-following "CREATE INDEX \\"IDX_ipns_records_user_id\\"" to "CREATE INDEX IF NOT EXISTS \\"IDX_ipns_records_user_id\\"". Do NOT alter the schema, columns, constraints, or any other migration step. Keep the SQL otherwise byte-identical so the Migration Drift Check still passes.`,
  },
]

phase('Fix')
const results = await parallel(
  tasks.map((t) => () => agent(t.prompt, { label: t.label, phase: 'Fix', schema: FIX_SCHEMA }))
)
return results.map((r, i) => ({ task: tasks[i].label, result: r }))

